Contract EvaluateLoanRequestModule::chooseOneForReview(requestid: Integer): LoanRequest {
	definition:
		chosenLoanRequest: LoanRequest = CurrentLoanRequests->any(l|l.RequestID = requestid)
	precondition:
		CurrentLoanRequests->excludes(chosenLoanRequest)
	postcondition:
		if chosenLoanRequest.oclIsNew() 
		then CurrentLoanRequest = chosenLoanRequest 
		endif 
}
